'use strict';
const $ = id => document.getElementById(id);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes = n => n ? (n >= 1073741824 ? (n/1073741824).toFixed(2)+' GiB' : (n/1048576).toFixed(1)+' MiB') : '大小待补充';
const number = n => Number(n||0).toLocaleString('zh-CN');
const date = n => n ? new Date(n*1000).toLocaleDateString('zh-CN') : '待补充';
const STATUS = {missing:'未翻译',pending:'处理中',partial:'部分完成',complete:'正文已导入',review:'待复核',stale:'原文已更新'};
const TAG_ZH = {};
const tagText = text => TAG_ZH[text] || text;
async function loadTagTranslations(){try{const response=await fetch('/tag-translations.json');if(!response.ok)throw new Error('标签汉化表读取失败');Object.assign(TAG_ZH,await response.json())}catch(error){console.warn('标签汉化不可用，已保留 Nexus 原文',error)}}
const displayTranslationStatus = m => m.game==='reddeadredemption2'&&m.translationStatus==='missing'?'中文摘要':STATUS[m.translationStatus];
const FILTER_KEYS=['q','category','tag','author','adult','translation','variants','localImages','sort','tagsAll','tagsAny','tagsExclude','updatedFrom','updatedTo'];
const ARRAY_FILTERS=new Set(['tagsAll','tagsAny','tagsExclude']);
const VIEWS=new Set(['browse','favorites','recent','profiles','translations','settings']);
const TABS=new Set(['overview','images','files','requirements','description']);
const state = {token:'',view:'browse',game:'',page:1,pageSize:48,filters:{},games:[],profiles:[],savedFilters:[],activeProfiles:{},detail:null,tab:'overview',language:'zh',compare:new Set(),imagePage:1,galleryIndex:0,galleryTotal:0,galleryItems:[],request:0,returnFocus:null,controllers:{},eventSeq:0,pollTimer:null,pollActive:false,eventsInitialized:false,jobs:new Map()};
let persistTimer, searchTimer, toastTimer, lastJobKey='',restoringHistory=false;
async function api(path, body, options={}) {
  const response = await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json','X-Mod-Token':state.token},body:body===undefined?undefined:JSON.stringify(body),signal:options.signal});
  const result = await response.json();
  if(!result.ok) throw new Error(result.error?.message || '请求失败');
  return result.data;
}
function toast(message,error=false){$('toast').textContent=message;$('toast').hidden=false;$('toast').classList.toggle('error',error);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000)}
async function action(fn){try{return await fn()}catch(error){if(error.name==='AbortError')return null;toast(error.message,true);console.error(error);return null}}
function serializableView(){return {game:state.game,view:state.view,filters:state.filters,page:state.page,pageSize:state.pageSize,activeProfiles:state.activeProfiles,language:state.language,detail:state.detail?.id||'',tab:state.tab}}
function cleanView(value={}){const page=Math.max(1,Number(value.page)||1),pageSize=[24,48,96].includes(Number(value.pageSize))?Number(value.pageSize):48;return {game:String(value.game||''),view:VIEWS.has(value.view)?value.view:'browse',filters:value.filters&&typeof value.filters==='object'&&!Array.isArray(value.filters)?value.filters:{},page,pageSize,activeProfiles:value.activeProfiles&&typeof value.activeProfiles==='object'?value.activeProfiles:{},language:['zh','original','both'].includes(value.language)?value.language:'zh',detail:String(value.detail||''),tab:TABS.has(value.tab)?value.tab:'overview'}}
function readInitialView(){let saved={};try{saved=JSON.parse(localStorage.getItem('mod-browser-view-v2')||'{}')}catch(error){console.warn('本地浏览偏好不可用',error)}const value=cleanView(saved),query=new URLSearchParams(location.search);if(query.has('view'))value.view=VIEWS.has(query.get('view'))?query.get('view'):'browse';if(query.has('game'))value.game=query.get('game');if(query.has('page'))value.page=Math.max(1,Number(query.get('page'))||1);if(query.has('limit'))value.pageSize=[24,48,96].includes(Number(query.get('limit')))?Number(query.get('limit')):48;if(query.has('detail'))value.detail=query.get('detail');if(query.has('tab'))value.tab=TABS.has(query.get('tab'))?query.get('tab'):'overview';const urlFilters={...value.filters};for(const key of FILTER_KEYS){if(!query.has(key))continue;const raw=query.get(key);if(ARRAY_FILTERS.has(key)){try{const parsed=JSON.parse(raw);urlFilters[key]=Array.isArray(parsed)?parsed.map(String):[]}catch{urlFilters[key]=[]}}else urlFilters[key]=['updatedFrom','updatedTo'].includes(key)?Number(raw)||'':raw}value.filters=urlFilters;return value}
function viewUrl(){const value=serializableView(),query=new URLSearchParams();if(value.view!=='browse')query.set('view',value.view);if(value.game)query.set('game',value.game);if(value.page>1)query.set('page',value.page);if(value.pageSize!==48)query.set('limit',value.pageSize);for(const [key,item] of Object.entries(value.filters)){if(item===undefined||item===''||(Array.isArray(item)&&!item.length))continue;query.set(key,Array.isArray(item)?JSON.stringify(item):item)}if(value.detail){query.set('detail',value.detail);query.set('tab',value.tab)}return '/'+(query.size?'?'+query:'')}
function saveView(push=false){clearTimeout(persistTimer);persistTimer=setTimeout(()=>{const value=serializableView();try{localStorage.setItem('mod-browser-view-v2',JSON.stringify(value))}catch(error){console.warn('无法保存本地浏览偏好',error)}if(restoringHistory)return;const historyState={...value,scrollY:window.scrollY,focusId:document.activeElement?.id||''};history[push?'pushState':'replaceState'](historyState,'',viewUrl())},60)}
function safeLink(url,text){return /^https?:\/\//i.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`:esc(text)}
function badge(text,kind=''){return `<span class="badge ${kind}">${esc(text)}</span>`}
function selectedTag(text){return ['tag','tagsAll','tagsAny','tagsExclude'].some(key=>Array.isArray(state.filters[key])?state.filters[key].includes(text):state.filters[key]===text)}
function tagBadge(text,add=true){const zh=tagText(text),original=zh===text?'':`；Nexus 原标签：${text}`;return `<span class="tag-choice"><button type="button" class="badge tag-link" data-filter-tag="${esc(text)}" aria-pressed="${selectedTag(text)}" aria-label="只查看标签“${esc(zh)}”${esc(original)}" title="只查看当前游戏的该标签">${esc(zh)}</button>${add?`<button type="button" class="tag-add" data-add-filter="${esc(text)}" aria-label="将“${esc(zh)}”加入当前组合筛选" title="加入组合筛选">+</button>`:''}</span>`}
function tagPreview(tags){const visible=(tags||[]).slice(0,3),remaining=(tags||[]).length-visible.length;return visible.map(tag=>tagBadge(tag)).join('')+(remaining?`<button class="badge more-tags" data-action="open">另 ${remaining} 个</button>`:'')}
function detailUrl(id,tab='overview'){const url=new URL(viewUrl(),location.origin);url.searchParams.set('detail',id);url.searchParams.set('tab',tab);return url.pathname+url.search}
function queryParams(extra={}){const query=new URLSearchParams();for(const [key,value] of Object.entries({...state.filters,...extra})){if(value===undefined||value===''||(Array.isArray(value)&&!value.length))continue;query.set(key,Array.isArray(value)?JSON.stringify(value):value)}return query}
function download(url){const a=document.createElement('a');a.href=url;a.download=decodeURIComponent(url.split('/').pop());document.body.append(a);a.click();a.remove()}
function form(title,fields){return new Promise(resolve=>{const dialog=$('formDialog');$('dialogTitle').textContent=title;$('dialogFields').innerHTML=fields;dialog.showModal();let finished=false;const close=value=>{if(finished)return;finished=true;dialog.close();resolve(value)};$('dialogForm').onsubmit=e=>{e.preventDefault();close(Object.fromEntries(new FormData(e.target)))};$('dialogCancel').onclick=()=>close(null);dialog.oncancel=()=>close(null);dialog.querySelector('input,select,textarea')?.focus()})}

async function refreshGames(){state.games=await api('/api/games');$('games').innerHTML=`<button class="game-btn ${!state.game?'active':''}" data-game="">全部游戏<small>${number(state.games.reduce((a,g)=>a+g.count,0))}</small></button>`+state.games.map(g=>`<button class="game-btn ${state.game===g.id?'active':''}" data-game="${esc(g.id)}"><span>${esc(g.title)}${g.available?'':' · 离线'}</span><small>${g.count}</small></button>`).join('');$('connection').textContent='本地运行 · '+state.games.length+' 个游戏'}
async function facets(options={}){const data=await api('/api/facets?'+queryParams({game:state.game}),undefined,options);for(const [id,key,label] of [['category','categories','用途'],['author','authors','作者']]){const selected=state.filters[id]||'',values={...data[key]};if(selected&&!Object.hasOwn(values,selected))values[selected]=0;$(id).innerHTML=`<option value="">全部${label}</option>`+Object.entries(values).map(([v,n])=>`<option value="${esc(v)}">${esc(v)} (${n})</option>`).join('');$(id).value=selected}const chosen=new Set(['tag','tagsAll','tagsAny','tagsExclude'].flatMap(key=>Array.isArray(state.filters[key])?state.filters[key]:state.filters[key]?[state.filters[key]]:[])),tags={...data.tags};for(const value of chosen)if(!Object.hasOwn(tags,value))tags[value]=0;$('tag').innerHTML='<option value="">选择标签…</option>'+Object.entries(tags).map(([v,n])=>`<option value="${esc(v)}">${esc(tagText(v)!==v?tagText(v)+' · '+v:v)} (${n})</option>`).join('')}
function unixDate(value){if(!value)return '';const dateValue=new Date(Number(value)*1000);if(Number.isNaN(dateValue.valueOf()))return '';return [dateValue.getFullYear(),String(dateValue.getMonth()+1).padStart(2,'0'),String(dateValue.getDate()).padStart(2,'0')].join('-')}
function dateUnix(value,end=false){if(!value)return '';const [year,month,day]=value.split('-').map(Number),dateValue=new Date(year,month-1,day,end?23:0,end?59:0,end?59:0,end?999:0);return Math.floor(dateValue.getTime()/1000)}
function syncFilters(){for(const id of ['category','author','adult','translation','sort'])$(id).value=state.filters[id]||(id==='sort'?'downloads':'');for(const id of ['variants','localImages'])$(id).checked=state.filters[id]==='1';$('search').value=state.filters.q||'';$('pageSize').value=String(state.pageSize);$('updatedFrom').value=unixDate(state.filters.updatedFrom);$('updatedTo').value=unixDate(state.filters.updatedTo,true)}
function renderChips(){const labels={category:'用途',tag:'标签',tagsAll:'全部包含',tagsAny:'任一包含',tagsExclude:'排除',author:'作者',adult:'内容',translation:'中文',variants:'多个文件',localImages:'本地图片',q:'搜索',updatedFrom:'更新起始',updatedTo:'更新截止'};const parts=[];for(const [key,value] of Object.entries(state.filters)){if(!value||key==='sort')continue;const values=Array.isArray(value)?value:[value];values.forEach((item,index)=>{const shown=['tag','tagsAll','tagsAny','tagsExclude'].includes(key)?tagText(item):key==='translation'?STATUS[item]:key==='adult'?(item==='yes'?'成人标记':'无成人标记'):['updatedFrom','updatedTo'].includes(key)?unixDate(item):item==='1'?'是':item;parts.push(`<button class="chip" data-clear="${esc(key)}" data-index="${index}">${labels[key]||key}：${esc(shown)} ×</button>`)})}$('chips').innerHTML=parts.join('')+(parts.length?'<button class="chip" data-clear="all">清空筛选</button>':'')}
async function browse(){
  const request=++state.request;renderChips();saveView();state.controllers.browse?.abort();const controller=new AbortController();state.controllers.browse=controller;$('cards').setAttribute('aria-busy','true');
  const query=queryParams({game:state.game,page:state.page,limit:state.pageSize});
  if(state.view==='favorites')query.set('favorite','1');
  if(state.view==='recent'){query.set('recent','1');if(!state.filters.sort)query.set('sort','recent')}
  const [data]=await Promise.all([api('/api/mods?'+query,undefined,{signal:controller.signal}),facets({signal:controller.signal})]);if(request!==state.request)return;
  if(data.page>data.pages){state.page=data.pages;return browse()}
  const game=state.games.find(g=>g.id===state.game),baseTitle=game?.title||'全部游戏';$('pageTitle').textContent=state.view==='favorites'?'我的收藏':state.view==='recent'?'最近浏览':state.filters.tag?`${baseTitle} · 标签：${tagText(state.filters.tag)}`:baseTitle;
  $('resultSummary').textContent=`${number(data.total)} 个 MOD · 第 ${data.page}/${data.pages} 页 · 每页 ${state.pageSize} 项`;
  $('cards').innerHTML=data.items.map(m=>`<article class="card" data-id="${esc(m.id)}"><a class="cover" data-action="open" href="${esc(detailUrl(m.id))}" aria-label="预览 ${esc(m.zh.name||m.name)}">${m.cover?`<img loading="lazy" decoding="async" src="${esc(m.cover)}?placeholder=1" alt="${esc(m.name)}">`:'<span class="no-image">暂无本地图片</span>'}<span class="image-label">${m.imageCount||0} 张参考图</span></a><div class="card-body"><div class="game-label">${esc(m.gameTitle)}</div><a class="card-title" data-action="open" href="${esc(detailUrl(m.id))}">${esc(m.zh.name||m.name)}</a><div class="original">${m.zh.name?esc(m.name)+' · ':''}${esc(m.author||'作者待补充')}</div><p class="summary">${esc(m.summary)}</p><div class="badges">${badge(m.group)}${badge((m.fileCount||0)+' 个文件',m.fileCount>1?'warn':'')}${badge(displayTranslationStatus(m),m.translationStatus==='complete'?'good':'')}${m.adult?badge('成人标记','warn'):''}</div><div class="card-tag-block"><div class="tag-label">Nexus 官方标签（中文）· ${(m.tags||[]).length}</div><div class="badges card-tags">${(m.tags||[]).length?tagPreview(m.tags):'<span class="tag-empty">Nexus 未设置标签</span>'}</div></div><div class="metrics"><span>下载 ${number(m.downloads)}</span><span>更新 ${date(m.updated)}</span></div><div class="card-actions"><button class="star" data-action="favorite" aria-pressed="${m.favorite}" aria-label="${m.favorite?'取消收藏':'收藏'} ${esc(m.name)}">${m.favorite?'已收藏':'收藏'}</button><button data-action="files">${m.fileCount>1?'选择变体':'加入搭配'}</button><a class="full-link" href="${esc(detailUrl(m.id,'description'))}">完整详情</a></div></div></article>`).join('');
  $('cards').querySelectorAll('img').forEach(im=>im.addEventListener('error',()=>{im.replaceWith(Object.assign(document.createElement('span'),{className:'no-image',textContent:'图片未下载或暂不可用'}))},{once:true}));
  $('cards').setAttribute('aria-busy','false');$('empty').hidden=data.total>0;$('pageInfo').textContent=`${data.page} / ${data.pages}`;$('prevPage').disabled=data.page<=1;$('nextPage').disabled=data.page>=data.pages;
}
async function setView(view){if(state.detail)closeDetail(true);state.view=view;for(const name of ['browse','profiles','translations','settings'])$(name+'View').hidden=name==='browse'?!['browse','favorites','recent'].includes(view):name!==view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('sidebar').classList.remove('open');saveView();if(['browse','favorites','recent'].includes(view))await browse();else if(view==='profiles')await profilesView();else if(view==='translations')await translationsView();else await settingsView()}
async function changeGame(game){state.game=game;state.page=1;state.filters={q:state.filters.q||'',sort:state.filters.sort||'downloads'};syncFilters();await refreshGames();await setView(['profiles','translations'].includes(state.view)?state.view:'browse')}
async function filterByTag(tag){
  const game=state.detail?.game||state.game,sort=state.filters.sort||'downloads';
  if(state.detail)closeDetail(true);
  state.game=game;state.page=1;state.filters={tag,sort};
  await refreshGames();syncFilters();await setView('browse');
  window.scrollTo(0,0);$('main').focus({preventScroll:true});
}
async function addTagFilter(tag){const mode=$('tagMode').value||'tagsAll';const values=Array.isArray(state.filters[mode])?[...state.filters[mode]]:[];if(!values.includes(tag))values.push(tag);delete state.filters.tag;state.filters[mode]=values;state.page=1;syncFilters();await browse()}

async function openDetail(id,tab='overview',fromHistory=false){
  state.controllers.detail?.abort();const controller=new AbortController();state.controllers.detail=controller;if(!fromHistory)history.replaceState({...serializableView(),scrollY:window.scrollY,focusId:document.activeElement?.id||''},'',viewUrl());state.returnFocus=document.activeElement;const detail=await api('/api/mod?id='+encodeURIComponent(id),undefined,{signal:controller.signal});if(controller.signal.aborted)return;state.detail=detail;state.tab=tab;state.imagePage=1;
  $('detail').hidden=false;document.body.classList.add('detail-open');$('detail').scrollTop=0;$('closeDetail').focus();
  $('fullDetailLink').href=detailUrl(id,tab);if(!fromHistory)saveView(true);await api('/api/recent',{id});await refreshDetail();renderCompareTray();
}
function closeDetail(fromHistory=false){if(!state.detail)return;if(!fromHistory&&history.state?.detail){history.back();return}state.controllers.detail?.abort();$('detail').hidden=true;document.body.classList.remove('detail-open');state.detail=null;saveView();if(state.returnFocus?.isConnected)state.returnFocus.focus()}
function translatedText(object,field){const original=object[field]||'',zh=object.zh?.[field];if(state.language==='original')return `<div class="prose">${esc(original||'作者未提供此项')}</div>`;if(!zh){const curated=object.game==='reddeadredemption2'&&['function','details','compatibility','risk','variantRule'].includes(field)&&/[\u3400-\u9fff]/.test(original);return `<div class="translation-note">${curated?'本地中文摘要；安装条件请结合作者原文核实':'中文尚未导入，以下保留原文'}</div><div class="prose">${esc(original||'作者未提供此项')}</div>`}return `<div class="translation-note">Gemini 机器翻译 · 请结合作者原文核实关键安装条件</div><div class="prose">${esc(zh)}</div>${state.language==='both'?`<h3>作者原文</h3><div class="prose">${esc(original)}</div>`:''}`}
async function refreshDetail(){const m=state.detail;if(!m)return;$('fullDetailLink').href=detailUrl(m.id,state.tab);$('detailHeading').innerHTML=`<div class="game-label">${esc(m.gameTitle)} · ${esc(m.group)}</div><h2>${esc(m.zh.name||m.name)}</h2>${m.zh.name?`<p class="muted">${esc(m.name)}</p>`:''}<div class="badges">${badge(displayTranslationStatus(m))}${m.adult?badge('成人标记','warn'):''}${badge(m.fileCount+' 个文件')}</div>`;$('detailFavorite').textContent=m.favorite?'取消收藏':'收藏';$('detailFavorite').setAttribute('aria-pressed',String(m.favorite));$('language').value=state.language;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));
  if(state.tab==='overview'){$('detailBody').innerHTML=`${translatedText(m,'function')}<h3>资料</h3><div class="info-grid"><div class="info"><small>作者</small>${esc(m.author||'待补充')}</div><div class="info"><small>页面版本</small>${esc(m.version||'待补充')}</div><div class="info"><small>下载 / 点赞</small>${number(m.downloads)} / ${number(m.endorsements)}</div><div class="info"><small>更新时间</small>${date(m.updated)}</div></div><h3>Nexus 官方标签（中文）· ${(m.tags||[]).length}</h3><div class="badges detail-tags">${(m.tags||[]).length?m.tags.map(tagBadge).join(''):'<span class="tag-empty">Nexus 页面未设置标签</span>'}</div><p class="muted tag-hint">中文名称用于显示，筛选仍使用 Nexus 官方原标签；悬停可查看英文原文，点击可筛选当前游戏中的全部同标签 MOD。</p><p>${safeLink(m.nexus,'打开 Nexus 发布页')}</p><div class="actions"><button id="translateOne">导出这个 MOD 的翻译任务</button><button id="editResource">整理资料</button><button id="editHistory">修改记录</button></div><div id="historyBody"></div>`;$('translateOne').onclick=()=>action(async()=>{await api('/api/translations/export',{modId:m.id});toast('正在生成翻译交接包');wakeJobs()});$('editResource').onclick=()=>action(()=>editResource(m.id));$('editHistory').onclick=()=>action(async()=>{const rows=await api('/api/content/history?id='+encodeURIComponent(m.id));$('historyBody').innerHTML=rows.map(r=>`<div class="file-item"><small>${new Date(r.created*1000).toLocaleString('zh-CN')}</small><p>${esc(r.note)}</p><button data-undo-edit="${r.id}">恢复到此次修改前</button></div>`).join('')||'<p class="muted">还没有本地修改记录。</p>';$('historyBody').querySelectorAll('[data-undo-edit]').forEach(b=>b.onclick=()=>action(async()=>{const h=rows.find(r=>r.id===Number(b.dataset.undoEdit));const before=JSON.parse(h.before_patch),current=await api('/api/resource?id='+encodeURIComponent(m.id));const patch=Object.fromEntries([...new Set([...Object.keys(current.patch),...Object.keys(before)])].map(k=>[k,k in before?before[k]:null]));if(!Object.keys(patch).length){toast('没有需要恢复的字段');return}const preview=await api('/api/content/preview',{records:[{resourceId:m.id,baseRevision:current.revision,patch,note:'恢复修改记录 '+h.id+' 之前的资料'}]});if(preview.errors.length)throw new Error(preview.errors[0].error);await api('/api/content/apply',{previewId:preview.previewId});state.detail=await api('/api/mod?id='+encodeURIComponent(m.id));await refreshDetail();toast('资料已恢复；原译文可能需要更新')}))})}
  if(state.tab==='description')$('detailBody').innerHTML=translatedText(m,'details');
  if(state.tab==='requirements'){$('detailBody').innerHTML=`<h3>前置依赖与来源</h3>${m.requirements.length?m.requirements.map(r=>`<div class="file-item"><strong>${esc(r.name)}</strong><p>${esc(r.notes)}</p><div class="file-meta">${esc(({required:'必需',optional:'可选',unknown:'待核实'})[r.kind]||'待核实')} · ${esc(r.evidence)} · ${esc(r.availability)}</div>${r.resourceId?`<button data-related="${esc(r.resourceId)}">查看本地资料</button>`:safeLink(r.url,'查看依赖来源')}</div>`).join(''):'<p class="muted">未取得结构化依赖记录，请核对完整作者说明。</p>'}<h3>兼容说明</h3>${translatedText(m,'compatibility')}<h3>冲突与风险</h3><p class="translation-note">${esc(m.conflictEvidence)}</p>${translatedText(m,'risk')}<h3>变体规则</h3>${translatedText(m,'variantRule')}`;$('detailBody').querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>action(()=>openDetail(b.dataset.related)))}
  if(state.tab==='files')await renderFiles();
  if(state.tab==='images')await renderImages();
}
async function loadProfiles(){state.profiles=await api('/api/profiles');return state.profiles}
async function loadSavedFilters(selectedId=''){state.savedFilters=await api('/api/saved-filters');$('savedFilter').innerHTML='<option value="">已保存筛选…</option>'+state.savedFilters.map(item=>`<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('');$('savedFilter').value=selectedId;$('deleteFilter').disabled=!selectedId;return state.savedFilters}
async function saveCurrentFilter(){const selected=state.savedFilters.find(item=>item.id===$('savedFilter').value),data=await form('保存当前筛选',`<label>名称<input name="name" required maxlength="120" value="${esc(selected?.name||'')}" placeholder="例如：最近更新的服装"></label>`);if(!data)return;const saved=await api('/api/saved-filters/save',{id:selected?.id,name:data.name,game:state.game,filters:state.filters,revision:selected?.revision});await loadSavedFilters(saved.id);toast(selected?'筛选已更新':'筛选已保存')}
async function deleteCurrentFilter(){const selected=state.savedFilters.find(item=>item.id===$('savedFilter').value);if(!selected)return;await api('/api/saved-filters/delete',{id:selected.id,revision:selected.revision});await loadSavedFilters();toast('已删除保存的筛选')}
async function applySavedFilter(id){const selected=state.savedFilters.find(item=>item.id===id);$('deleteFilter').disabled=!selected;if(!selected)return;state.game=selected.game||'';state.filters=JSON.parse(JSON.stringify(selected.filters||{}));state.page=1;await refreshGames();syncFilters();await setView('browse')}
function renderCompareTray(){$('compareTray').hidden=state.compare.size===0;$('compareSummary').textContent=`已选 ${state.compare.size}/3 个具体文件`;$('compareOpen').disabled=state.compare.size<2}
async function compareSelected(){if(state.compare.size<2)return;const query=new URLSearchParams({ids:JSON.stringify([...state.compare])}),result=await api('/api/v2/files.compare?'+query),files=result.items.map(item=>({id:item.resourceId,...item.data}));const fields=[['名称',f=>f.name],['作者文件说明',f=>f.description||'待补充'],['版本',f=>f.version||'待补充'],['类别',f=>f.category||'待补充'],['大小',f=>bytes(f.bytes)],['FileId',f=>f.fileId||'未匹配']];$('compareBody').innerHTML=`<div class="compare-wrap"><table class="compare-table"><thead><tr><th>比较项目</th>${files.map(f=>`<th>${esc(f.name||f.id)}</th>`).join('')}</tr></thead><tbody>${fields.map(([name,fn])=>`<tr><th>${name}</th>${files.map(f=>`<td>${esc(fn(f))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('compareDialog').showModal()}
async function ensureProfile(game){await loadProfiles();let pid=state.activeProfiles[game];if(state.profiles.some(p=>p.id===pid&&p.game===game))return pid;const existing=state.profiles.find(p=>p.game===game);if(existing)pid=existing.id;else{const data=await form('给这套搭配起个名字',`<label>搭配名称<input name="name" value="我的搭配" required maxlength="120"></label><label>备注<textarea name="notes" placeholder="例如：日常游玩、拍照用"></textarea></label>`);if(!data)return null;pid=(await api('/api/profile/save',{game,...data})).id;await loadProfiles()}state.activeProfiles[game]=pid;saveView();return pid}
async function renderFiles(){const m=state.detail;await loadProfiles();let pid=state.activeProfiles[m.game];if(!state.profiles.some(p=>p.id===pid&&p.game===m.game))pid=state.profiles.find(p=>p.game===m.game)?.id;const profile=pid?await api('/api/profile?id='+encodeURIComponent(pid)):null;if(pid)state.activeProfiles[m.game]=pid;const selected=new Map((profile?.items||[]).map(i=>[i.fileId,i]));
  $('detailBody').innerHTML=`<div class="notice">逐个选择需要的主文件、组件或变体。多个文件不一定互斥，也不一定能一起使用，请核对作者说明。</div><label>加入哪套搭配<select id="targetProfile"><option value="">选择或创建搭配</option>${state.profiles.filter(p=>p.game===m.game).map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="actions"><button id="newTargetProfile">新建搭配</button><button id="compareFiles" ${state.compare.size<2?'disabled':''}>比较已勾选 (${state.compare.size}/3)</button></div><div id="comparison"></div>${m.files.map((f,i)=>`<section class="file-item ${selected.has(f.id)?'selected':''}" data-file="${i}"><h3>${esc(f.zh?.name||f.name)}</h3>${f.zh?.name?`<div class="original">${esc(f.name)}</div>`:''}<div class="file-meta">${esc(f.category||'文件类别待补充')} · v${esc(f.version||'待补充')} · ${bytes(f.bytes)} · ${date(f.uploaded)}<br>${f.fileId?'FileId '+f.fileId:'未匹配 Nexus FileId'} · ${esc(f.metadataSource)}</div>${f.description?`<details><summary>作者文件说明</summary>${translatedText(f,'description')}</details>`:'<p class="muted">作者文件说明待补充</p>'}<label>归档副本<select class="copy-select">${f.copies.map((c,n)=>`<option value="${n}" ${selected.get(f.id)?.storedPath===c.storedPath?'selected':''}>${n+1}. ${esc(c.label)} · ${esc(c.path)}</option>`).join('')}</select></label><div class="copy-path">${esc(f.copies.find(c=>c.storedPath===selected.get(f.id)?.storedPath)?.path||f.copies[0]?.path||'没有本地副本')}</div><div class="actions"><button data-file-action="toggle" class="${selected.has(f.id)?'':'primary'}">${selected.has(f.id)?'从搭配移除':'加入搭配'}</button><button data-file-action="edit">整理资料</button><button data-file-action="reveal">定位文件</button><button data-file-action="copy">复制路径</button><label class="check"><input type="checkbox" data-compare="${i}" ${state.compare.has(f.id)?'checked':''}>比较</label></div></section>`).join('')}`;
  $('targetProfile').onchange=()=>action(async()=>{state.activeProfiles[m.game]=$('targetProfile').value;saveView();await renderFiles()});
  $('newTargetProfile').onclick=()=>action(async()=>{await newProfile(m.game);await renderFiles()});
  $('detailBody').querySelectorAll('.file-item').forEach(el=>{const f=m.files[Number(el.dataset.file)];const copy=()=>f.copies[Number(el.querySelector('select').value)];el.querySelector('select').onchange=()=>action(async()=>{el.querySelector('.copy-path').textContent=copy().path;if(selected.has(f.id)){await api('/api/profile/select',{profileId:pid,fileId:f.id,copyPath:copy().storedPath,selected:true});toast('已切换搭配使用的副本')}});el.querySelectorAll('[data-file-action]').forEach(b=>b.onclick=()=>action(async()=>{const c=copy();if(!c)throw new Error('没有可用副本');if(b.dataset.fileAction==='edit'){await editResource(f.id)}else if(b.dataset.fileAction==='copy'){await navigator.clipboard.writeText(c.path);toast('路径已复制')}else if(b.dataset.fileAction==='reveal'){await api('/api/reveal',{fileId:f.id,copyPath:c.storedPath})}else{const target=pid||await ensureProfile(m.game);if(!target)return;await api('/api/profile/select',{profileId:target,fileId:f.id,copyPath:c.storedPath,selected:!selected.has(f.id)});toast(selected.has(f.id)?'已移除':'已加入搭配');await renderFiles()}}));el.querySelector('[data-compare]').onchange=e=>{if(e.target.checked&&state.compare.size>=3){e.target.checked=false;toast('一次最多比较 3 个文件');return}e.target.checked?state.compare.add(f.id):state.compare.delete(f.id);$('compareFiles').textContent=`比较已勾选 (${state.compare.size}/3)`;$('compareFiles').disabled=state.compare.size<2;renderCompareTray()}});
  $('compareFiles').onclick=()=>action(compareSelected);
}
async function addMod(){const m=state.detail;if(m.files.length!==1){state.tab='files';await refreshDetail();return}const pid=await ensureProfile(m.game);if(!pid)return;const f=m.files[0],copy=f.copies.find(c=>c.status==='available')||f.copies[0];if(!copy)throw new Error('没有归档副本');await api('/api/profile/select',{profileId:pid,fileId:f.id,copyPath:copy.storedPath,selected:true});toast('已加入搭配：'+(state.profiles.find(p=>p.id===pid)?.name||''));state.tab='files';await refreshDetail()}
async function renderImages(){const detailId=state.detail?.id,page=state.imagePage;if(!detailId)return;state.controllers.images?.abort();const controller=new AbortController();state.controllers.images=controller;const data=await api(`/api/images?id=${encodeURIComponent(detailId)}&page=${page}`,undefined,{signal:controller.signal});if(controller.signal.aborted||state.detail?.id!==detailId||state.imagePage!==page||state.tab!=='images')return;state.galleryTotal=data.total;state.galleryItems=data.items;$('detailBody').innerHTML=`<p class="muted">${data.total} 张参考图 · 每次读取 24 张。本地没有的图片可前往来源查看。</p><div class="gallery-grid">${data.items.map((im,i)=>`<button data-image="${i}" aria-label="查看第 ${im.ordinal+1} 张图片"><img loading="lazy" src="${esc(im.src)}?placeholder=1" alt="${esc(im.zh?.caption||im.caption||'参考图 '+(im.ordinal+1))}"></button>`).join('')}</div><div class="pagination"><button id="imagesPrev" ${state.imagePage===1?'disabled':''}>上一组</button><span>${state.imagePage}/${Math.max(1,Math.ceil(data.total/24))}</span><button id="imagesNext" ${state.imagePage*24>=data.total?'disabled':''}>下一组</button></div>`;$('detailBody').querySelectorAll('img').forEach(im=>im.addEventListener('error',()=>{im.replaceWith(Object.assign(document.createElement('span'),{className:'no-image',textContent:'图片未下载或暂不可用'}))},{once:true}));$('detailBody').querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>action(()=>openGallery((state.imagePage-1)*24+Number(b.dataset.image))));$('imagesPrev').onclick=()=>action(async()=>{state.imagePage--;await renderImages()});$('imagesNext').onclick=()=>action(async()=>{state.imagePage++;await renderImages()})}
async function openGallery(index){state.galleryIndex=index;await drawGallery();if(!$('gallery').open)$('gallery').showModal()}
async function drawGallery(){const page=Math.floor(state.galleryIndex/24)+1;const data=await api(`/api/images?id=${encodeURIComponent(state.detail.id)}&page=${page}`);const im=data.items[state.galleryIndex%24];if(!im)return;$('galleryTitle').textContent=state.detail.zh.name||state.detail.name;$('galleryImage').src=im.src+'?placeholder=1';$('galleryImage').alt=im.zh?.caption||im.caption||'MOD 参考图';$('galleryCaption').innerHTML=`${esc(im.zh?.caption||im.caption||im.source)} ${safeLink(im.remote_url,'查看原图来源')}`;$('galleryCount').textContent=`${state.galleryIndex+1} / ${data.total}`;$('galleryPrev').disabled=state.galleryIndex===0;$('galleryNext').disabled=state.galleryIndex>=data.total-1}

async function newProfile(game=state.game){const fields=`<label>游戏<select name="game" required>${state.games.map(g=>`<option value="${g.id}" ${g.id===game?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><label>搭配名称<input name="name" required maxlength="120" placeholder="例如：拍照搭配"></label><label>备注<textarea name="notes"></textarea></label>`;const data=await form('新建搭配',fields);if(!data)return;const p=await api('/api/profile/save',data);state.activeProfiles[data.game]=p.id;saveView();await loadProfiles();toast('搭配已创建');return p.id}
async function profilesView(){await loadProfiles();const profiles=state.profiles.filter(p=>!state.game||p.game===state.game);$('profilesView').innerHTML=`<div class="heading"><div><div class="eyebrow">具体文件 · 独立保存</div><h1>我的搭配</h1><p class="muted">收藏留住灵感，搭配记录你准备一起使用的文件。</p></div><button id="createProfile" class="primary">新建搭配</button></div><div class="profiles-grid">${profiles.map(p=>`<section class="profile-card"><h2>${esc(p.name)}</h2><p class="muted">${esc(state.games.find(g=>g.id===p.game)?.title||p.game)} · ${p.count} 个文件</p><p>${esc(p.notes||'暂无备注')}</p><button data-profile="${p.id}">打开搭配</button></section>`).join('')||'<div class="empty">还没有搭配。浏览 MOD 时选择具体文件即可开始。</div>'}</div><div id="profileDetail"></div>`;renderProfileImport();$('createProfile').onclick=()=>action(async()=>{const id=await newProfile();await profilesView();if(id)await showProfile(id)});$('profilesView').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>action(()=>showProfile(b.dataset.profile)))}
async function showProfile(id){const p=await api('/api/profile?id='+id);state.activeProfiles[p.game]=id;saveView();$('profileDetail').innerHTML=`<section class="panel"><h2>${esc(p.name)}</h2><p>${esc(p.notes)}</p><div class="actions"><button id="editProfile">名称与备注</button><button id="copyProfile">复制搭配</button><button id="exportJson" class="primary">导出 JSON 清单</button><button id="exportTxt">导出文字清单</button><button id="deleteProfile">删除搭配</button></div>${p.warnings.length?`<div class="notice">${p.warnings.map(w=>esc(w.message)).join('<br>')}</div>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>MOD / 文件</th><th>版本与大小</th><th>副本与状态</th><th>操作</th></tr></thead><tbody>${p.items.map((i,n)=>`<tr><td>${esc(i.modName)}<br><strong>${esc(i.name)}</strong></td><td>${esc(i.version||'待补充')}<br>${bytes(i.bytes)}</td><td>${esc(i.fileStatus.label)}${i.changed?' · 文件有变化，请重新选择':''}${i.orphan?' · 目录条目缺失':''}<br><small>${esc(i.fileStatus.path)}</small></td><td><button data-profile-remove="${n}">移除</button>${i.modId?`<button data-profile-mod="${esc(i.modId)}">详情</button>`:''}</td></tr>`).join('')}</tbody></table></div>${!p.items.length?'<p class="muted">还没有选择文件，去资料库挑选喜欢的 MOD 吧。</p>':''}</section>`;
  $('profileDetail').scrollIntoView({block:'nearest'});$('editProfile').onclick=()=>action(async()=>{const data=await form('编辑搭配',`<label>名称<input name="name" value="${esc(p.name)}" required></label><label>备注<textarea name="notes">${esc(p.notes)}</textarea></label>`);if(data){await api('/api/profile/save',{id,game:p.game,...data});await profilesView();await showProfile(id)}});
  $('copyProfile').onclick=()=>action(async()=>{const data=await form('复制搭配',`<label>新名称<input name="name" required value="${esc(p.name)} 副本"></label>`);if(data){const n=await api('/api/profile/copy',{id,...data});await profilesView();await showProfile(n.id)}});
  $('deleteProfile').onclick=()=>action(async()=>{if(confirm('删除这套搭配记录？MOD 文件不会删除。')){await api('/api/profile/delete',{id});await profilesView()}});
  for(const [button,format] of [['exportJson','json'],['exportTxt','txt']])$(button).onclick=()=>action(async()=>{const out=await api('/api/profile/export',{id,format});download(out.download)});
  $('profileDetail').querySelectorAll('[data-profile-remove]').forEach(b=>b.onclick=()=>action(async()=>{await api('/api/profile/select',{profileId:id,fileId:p.items[Number(b.dataset.profileRemove)].fileId,selected:false});await showProfile(id)}));$('profileDetail').querySelectorAll('[data-profile-mod]').forEach(b=>b.onclick=()=>action(()=>openDetail(b.dataset.profileMod,'files')));
}

async function translationsView(){const t=await api('/api/translations');$('translationsView').innerHTML=`<div class="heading"><div><div class="eyebrow">Gemini 3.8 Flash · 外部协作</div><h1>中文翻译</h1><p class="muted">导出任务 → 交给 Gemini → 导入结果。原文一直保留。</p></div></div><div class="stats">${Object.entries(STATUS).map(([k,v])=>`<div class="stat"><strong>${number(t.counts[k])}</strong><span>${v}</span></div>`).join('')}</div><section class="panel"><h2>1. 给 Gemini 准备资料</h2><p>任务包包含入口说明、术语表、原文、身份字段和结果示例。每批最多 20 个 MOD，长文分段；译文按原文版本校验。</p><label>导出范围<select id="translationGame"><option value="">全部游戏的缺失项</option>${state.games.map(g=>`<option value="${g.id}" ${g.id===state.game?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label><div class="actions"><button id="pilotExport" class="primary">导出首轮 12 个样本</button><button id="scopeExport">导出范围内待翻译项</button></div><p class="muted">任务不会调用付费 API。把压缩包交给另一个 Gemini 助手，让它先阅读“从这里开始.md”。</p><div id="packageList">${t.packages.slice(0,8).map(p=>`<p><a href="${esc(p.download)}" download>${esc(p.name)}</a></p>`).join('')}</div></section><section class="panel"><h2>2. 导入 Gemini 返回的结果</h2><p>选择 UTF-8 JSONL 或 JSON 文件。先检查身份、原文哈希、段落完整性和关键路径，再导入合格项。</p><label>结果文件<input id="resultFile" type="file" accept=".jsonl,.json,.txt"></label><div id="importPreview"></div></section><section class="panel"><h2>3. 需要复核的资料</h2>${t.issues.map(i=>`<p><button data-review="${esc(i.id)}">${esc(i.name)}</button> ${esc(STATUS[i.status])}</p>`).join('')||'<p class="muted">目前没有已检测到的过期或待复核 MOD。</p>'}${t.errors.length?`<details><summary>失败任务 (${t.errors.length})</summary>${t.errors.map(e=>`<p>${esc(e.resource_id)} · ${esc(e.field)}<br>${esc(e.error)}</p>`).join('')}</details>`:''}</section>`;
  $('pilotExport').onclick=()=>action(async()=>{await api('/api/translations/export',{pilot:true});toast('正在准备 12 个代表性样本');wakeJobs()});$('scopeExport').onclick=()=>action(async()=>{await api('/api/translations/export',{game:$('translationGame').value});toast('正在准备任务包');wakeJobs()});
  $('resultFile').onchange=()=>action(async()=>{const f=$('resultFile').files[0];if(!f)return;if(f.size>30*1024*1024)throw new Error('请把结果拆分到每份 30 MiB 以内');const p=await api('/api/translations/preview',{content:await f.text()});$('importPreview').innerHTML=`<div class="notice">可导入 ${p.valid} 段 · 已有重复 ${p.duplicates} 段 · 错误 ${p.errors.length} 段 · 尚未齐全 ${p.partial.length} 个字段。缺段字段保存进度，完整后才替换页面正文。</div>${p.samples.map(s=>`<div class="file-item"><small>${esc(s.resourceId)} · ${esc(s.field)}</small><p>${esc(s.translation)}</p></div>`).join('')}${p.errors.length?`<details><summary>查看错误</summary>${p.errors.map(e=>`<p>${esc(e.taskId)}：${esc(e.error)}</p>`).join('')}</details>`:''}${p.partial.length?`<details><summary>查看缺段字段</summary>${p.partial.map(f=>`<p>${esc(f.resourceId)} · ${esc(f.field)}：${f.received}/${f.total}</p>`).join('')}</details>`:''}<button id="commitImport" class="primary" ${!p.valid&&!p.errors.length?'disabled':''}>分批导入合格项并记录错误</button>`;$('commitImport').onclick=()=>action(async()=>{await api('/api/translations/import',{previewId:p.previewId,commitMode:'batched'});$('commitImport').disabled=true;wakeJobs()})});$('translationsView').querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>action(()=>openDetail(b.dataset.review,'description')));
}
async function settingsView(){const s=await api('/api/settings');$('settingsView').innerHTML=`<div class="heading"><div><div class="eyebrow">资料索引 · 本地存储 · AI 接口</div><h1>资料与设置</h1></div></div><section class="panel"><h2>资料索引</h2><p>上次索引：${s.lastIndex.at?new Date(s.lastIndex.at*1000).toLocaleString('zh-CN'):'尚未建立'} · ${number(s.lastIndex.mods)} 个 MOD · ${number(s.lastIndex.files)} 个文件。</p><div class="actions"><button id="reindex">重新建立索引</button><button id="checkImages">检查本地图片</button><button id="backup">备份数据库</button></div><p class="muted">重建只更新目录资料，保留收藏、搭配和翻译。图片检查只读取文件，不下载图片。</p></section><section class="panel"><h2>游戏资料位置</h2><p>磁盘迁移后，可重新指定资料根目录。资源 ID 和已有搭配保持不变。</p>${state.games.map((g,i)=>`<div class="file-item"><strong>${esc(g.title)}</strong><p class="file-meta">登记位置：${esc(g.root)}</p><div class="folder-row"><input id="root${i}" aria-label="${esc(g.title)} 新根目录" value="${esc(s.roots[g.root]||g.root)}"><button data-root="${i}">保存位置</button></div></div>`).join('')}</section><section class="panel"><h2>让 AI 操作</h2><p>应用提供与界面共用的本机 JSON API，以及 ai.py 命令行。AI 可搜索、查看文件、管理收藏与搭配、导出和导入翻译；不需要模拟鼠标。</p><p><a href="/api/docs" target="_blank" rel="noopener">查看机器可读接口说明</a></p><p class="muted">AI 入口文档：本地MOD浏览器 / AI入口.md。所有写操作需要本地会话令牌，命令行自动读取。暂不提供实际安装接口。</p></section>`;
  renderContentInterchange();$('reindex').onclick=()=>action(async()=>{await api('/api/reindex',{});wakeJobs()});$('checkImages').onclick=()=>action(async()=>{await api('/api/images/check',{});wakeJobs()});$('backup').onclick=()=>action(async()=>{const b=await api('/api/backup',{});toast('备份已保存：'+b.path)});$('settingsView').querySelectorAll('[data-root]').forEach(b=>b.onclick=()=>action(async()=>{const i=Number(b.dataset.root);await api('/api/roots',{old:state.games[i].root,new:$('root'+i).value});await refreshGames();toast('资料根目录已更新')}));
}
const ACTIVE_JOB_STATUSES=new Set(['queued','running']);
function scheduleJobPoll(delay=0){clearTimeout(state.pollTimer);state.pollTimer=setTimeout(pollJobs,delay)}
function wakeJobs(){scheduleJobPoll(0)}
function latestJob(){return [...state.jobs.values()].sort((a,b)=>(a.updated||a.created||0)-(b.updated||b.created||0)).at(-1)}
function renderJobTray(showTerminal=true){const active=[...state.jobs.values()].filter(job=>ACTIVE_JOB_STATUSES.has(job.status)).sort((a,b)=>(a.updated||0)-(b.updated||0)).at(-1),job=active||latestJob();if(!job||(!active&&!showTerminal)){$('jobTray').hidden=true;return}const key=job.id+':'+job.status+':'+(job.updated||'');if(active){$('jobTray').hidden=false;$('jobTray').innerHTML=`<div class="job-head"><span>${esc(job.message||'后台作业正在执行')}</span><button id="cancelJob" ${job.cancel?'disabled':''}>${job.cancel?'正在停止':'停止'}</button></div><progress value="${job.done||0}" max="${job.total||1}"></progress>`;$('cancelJob').onclick=()=>action(async()=>{await api('/api/jobs/cancel',{id:job.id});wakeJobs()});lastJobKey=key;return}if(key===lastJobKey)return;const status={complete:'已完成',cancelled:'已停止',failed:'失败',blocked:'已阻塞'}[job.status]||job.status;$('jobTray').hidden=false;$('jobTray').innerHTML=`<div class="job-head"><span>${esc(job.message||'后台作业')} · ${esc(status)}</span><button id="dismissJob">收起</button></div>${job.result?.mods?`<p>${number(job.result.mods)} 个 MOD</p>`:''}${job.result?.missing!==undefined?`<p>不可用图片 ${number(job.result.missing)}</p>`:''}${job.result?.download?`<p><a href="${esc(job.result.download)}" download>下载翻译交接包（${number(job.result.segments)} 段）</a></p>`:''}${job.status==='complete'?'<button id="refreshJob">刷新相关内容</button>':''}`;$('dismissJob').onclick=()=>$('jobTray').hidden=true;if($('refreshJob'))$('refreshJob').onclick=()=>action(async()=>{await refreshGames();if(['browse','favorites','recent'].includes(state.view)){await facets();syncFilters();await browse()}else if(state.view==='profiles')await profilesView();else if(state.view==='translations')await translationsView();else await settingsView();$('jobTray').hidden=true;toast('已刷新相关内容')});lastJobKey=key}
async function pollJobs(){if(state.pollActive)return;state.pollActive=true;let hasMore=false;try{const initial=!state.eventsInitialized,query=new URLSearchParams({after:String(state.eventSeq),limit:'96',kind:'jobs'});if(initial)query.set('tail','true');const events=await api('/api/v2/events.read?'+query);state.eventsInitialized=true;state.eventSeq=Math.max(state.eventSeq,events.nextAfter||0);hasMore=events.hasMore;const ids=[...new Set(events.items.map(item=>item.id))];if(ids.length){const jobs=await Promise.all(ids.map(id=>api('/api/v2/jobs.read?id='+encodeURIComponent(id))));for(const job of jobs)state.jobs.set(job.id,job)}const active=[...state.jobs.values()].some(job=>ACTIVE_JOB_STATUSES.has(job.status));if(initial&&!active){const job=latestJob();if(job)lastJobKey=job.id+':'+job.status+':'+(job.updated||'');renderJobTray(false)}else renderJobTray(true);$('connection').textContent='本地运行 · '+state.games.length+' 个游戏'}catch(error){if(error.name!=='AbortError')$('connection').textContent='连接中断，将自动重试'}finally{state.pollActive=false;const active=[...state.jobs.values()].some(job=>ACTIVE_JOB_STATUSES.has(job.status));scheduleJobPoll(hasMore?0:active?750:5000)}}

$('navToggle').onclick=()=>$('sidebar').classList.toggle('open');
$('toggleFilters').onclick=()=>{const expanded=$('filtersPanel').classList.toggle('expanded');$('toggleFilters').setAttribute('aria-expanded',String(expanded));$('toggleFilters').textContent=expanded?'收起筛选':'展开筛选'};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>action(async()=>{state.page=1;await setView(b.dataset.view)}));
$('games').onclick=e=>{const b=e.target.closest('[data-game]');if(b)action(()=>changeGame(b.dataset.game))};
for(const id of ['category','author','adult','translation','sort','variants','localImages'])$(id).addEventListener('change',()=>action(async()=>{state.filters[id]=$(id).type==='checkbox'?($(id).checked?'1':''):$(id).value;state.page=1;await browse()}));
$('tag').addEventListener('change',()=>action(async()=>{const tag=$('tag').value;if(tag)await addTagFilter(tag);$('tag').value=''}));
for(const id of ['updatedFrom','updatedTo'])$(id).addEventListener('change',()=>action(async()=>{const value=dateUnix($(id).value,id==='updatedTo');if(value)state.filters[id]=value;else delete state.filters[id];state.page=1;await browse()}));
$('pageSize').addEventListener('change',()=>action(async()=>{state.pageSize=Number($('pageSize').value);state.page=1;await browse()}));
$('savedFilter').addEventListener('change',()=>action(()=>applySavedFilter($('savedFilter').value)));$('saveFilter').onclick=()=>action(saveCurrentFilter);$('deleteFilter').onclick=()=>action(deleteCurrentFilter);
$('search').addEventListener('input',()=>{state.filters.q=$('search').value;state.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(()=>action(()=>setView('browse')),200)});
$('chips').onclick=e=>{const b=e.target.closest('[data-clear]');if(b)action(async()=>{const key=b.dataset.clear;if(key==='all')state.filters={};else if(Array.isArray(state.filters[key])){const values=[...state.filters[key]];values.splice(Number(b.dataset.index),1);if(values.length)state.filters[key]=values;else delete state.filters[key]}else delete state.filters[key];syncFilters();state.page=1;await browse()})};
$('emptyClear').onclick=()=>action(async()=>{state.filters={};syncFilters();await browse()});
$('prevPage').onclick=()=>action(async()=>{state.page--;await browse();window.scrollTo(0,0)});$('nextPage').onclick=()=>action(async()=>{state.page++;await browse();window.scrollTo(0,0)});
$('cards').onclick=e=>{const add=e.target.closest('[data-add-filter]');if(add){e.preventDefault();action(()=>addTagFilter(add.dataset.addFilter));return}const tag=e.target.closest('[data-filter-tag]');if(tag){e.preventDefault();action(()=>filterByTag(tag.dataset.filterTag));return}const b=e.target.closest('[data-action]'),card=e.target.closest('[data-id]');if(!b||!card)return;if(b.tagName==='A'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0))return;e.preventDefault();action(async()=>{if(b.dataset.action==='favorite'){const enabled=b.getAttribute('aria-pressed')!=='true';await api('/api/favorite',{id:card.dataset.id,enabled});b.setAttribute('aria-pressed',String(enabled));b.textContent=enabled?'已收藏':'收藏';if(state.view==='favorites'&&!enabled)await browse()}else{await openDetail(card.dataset.id,b.dataset.action==='files'?'files':'overview');if(b.dataset.action==='files'&&state.detail.files.length===1)await addMod()}})};
$('closeDetail').onclick=()=>closeDetail();$('detailTabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(b)action(async()=>{state.controllers.images?.abort();state.tab=b.dataset.tab;saveView();await refreshDetail()})};
$('detailBody').onclick=e=>{const add=e.target.closest('[data-add-filter]');if(add){action(()=>addTagFilter(add.dataset.addFilter));return}const b=e.target.closest('[data-filter-tag]');if(b)action(()=>filterByTag(b.dataset.filterTag))};
$('detailFavorite').onclick=()=>action(async()=>{const m=state.detail;await api('/api/favorite',{id:m.id,enabled:!m.favorite});m.favorite=!m.favorite;await refreshDetail();if(['browse','favorites','recent'].includes(state.view))await browse()});$('detailAdd').onclick=()=>action(addMod);$('language').onchange=()=>action(async()=>{state.language=$('language').value;saveView();await refreshDetail()});
$('compareOpen').onclick=()=>action(compareSelected);$('compareClear').onclick=()=>{state.compare.clear();renderCompareTray();if(state.detail?.id&&state.tab==='files')action(renderFiles)};$('compareClose').onclick=()=>$('compareDialog').close();
$('galleryClose').onclick=()=>$('gallery').close();$('galleryPrev').onclick=()=>action(async()=>{state.galleryIndex--;await drawGallery()});$('galleryNext').onclick=()=>action(async()=>{state.galleryIndex++;await drawGallery()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('gallery').open&&!$('formDialog').open)closeDetail();if($('gallery').open){if(e.key==='ArrowLeft'&&state.galleryIndex>0){e.preventDefault();$('galleryPrev').click()}if(e.key==='ArrowRight'&&state.galleryIndex<state.galleryTotal-1){e.preventDefault();$('galleryNext').click()}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();$('search').focus()}});
window.addEventListener('popstate',event=>action(async()=>{restoringHistory=true;try{const target=cleanView(event.state||readInitialView()),detailId=target.detail;state.controllers.browse?.abort();state.controllers.detail?.abort();state.controllers.images?.abort();$('detail').hidden=true;document.body.classList.remove('detail-open');state.detail=null;Object.assign(state,{game:target.game,view:target.view,filters:target.filters,page:target.page,pageSize:target.pageSize,activeProfiles:target.activeProfiles,language:target.language,tab:target.tab});await refreshGames();syncFilters();await setView(target.view);if(detailId)await openDetail(detailId,target.tab,true);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));window.scrollTo(0,Number(event.state?.scrollY)||0);if(event.state?.focusId)document.getElementById(event.state.focusId)?.focus({preventScroll:true})}finally{restoringHistory=false}}));
action(async()=>{const [bootstrap]=await Promise.all([api('/api/bootstrap'),loadTagTranslations()]),saved=readInitialView();state.token=bootstrap.token;Object.assign(state,{game:saved.game,view:saved.view,filters:saved.filters,page:saved.page,pageSize:saved.pageSize,activeProfiles:saved.activeProfiles,language:saved.language,tab:saved.tab});await Promise.all([refreshGames(),loadSavedFilters()]);await facets();syncFilters();await setView(state.view);if(saved.detail)await openDetail(saved.detail,saved.tab,true);history.replaceState({...serializableView(),scrollY:window.scrollY,focusId:''},'',viewUrl());wakeJobs()});
